const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aswanDam = ee.Geometry.Point([32.879, 23.970]).buffer(5000); // Aswan High Dam, Egypt
  const gerdDam = ee.Geometry.Point([35.093, 11.215]).buffer(5000); // Grand Ethiopian Renaissance Dam
  const year = '2016';
  const startDate = ee.Date(year + '-01-01');
  const endDate = ee.Date(year + '-12-31');

  // 2. Data Acquisition & Check
  const viirsCollection = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG')
    .filterDate(startDate, endDate)
    .select('avg_rad');

  const imageCount = viirsCollection.size().getInfo();
  if (imageCount === 0) {
    console.log(`Evidence: No VIIRS images found for ${year}.`);
    console.log('A: C1');
    return;
  }

  // 3. Processing
  const meanImage = viirsCollection.mean();
  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  // 4. Calculation
  const aswanStats = meanImage.reduceRegion({
    reducer: reducer,
    geometry: aswanDam,
    scale: 1000,
    maxPixels: 1e9
  });

  const gerdStats = meanImage.reduceRegion({
    reducer: reducer,
    geometry: gerdDam,
    scale: 1000,
    maxPixels: 1e9
  });

  const aswanMean = aswanStats.get('avg_rad_mean').getInfo();
  const aswanCount = aswanStats.get('avg_rad_count').getInfo();

  const gerdMean = gerdStats.get('avg_rad_mean').getInfo();
  const gerdCount = gerdStats.get('avg_rad_count').getInfo();

  // 5. Validation & Final Answer
  console.log(`Evidence: VIIRS image count for ${year}: ${imageCount}`);

  if (aswanCount === 0 || gerdCount === 0) {
    console.log(`Evidence: No valid pixels in one or both regions.`);
    console.log(`Aswan Pixels: ${aswanCount}, GERD Pixels: ${gerdCount}`);
    console.log('A: C2');
    return;
  }

  if (aswanMean === null || gerdMean === null) {
      console.log(`Evidence: Calculation returned a null value.`);
      console.log(`Aswan Mean: ${aswanMean}, GERD Mean: ${gerdMean}`);
      console.log('A: C3');
      return;
  }

  console.log(`Evidence: Aswan Dam avg radiance: ${aswanMean.toFixed(4)} (from ${aswanCount} pixels)`);
  console.log(`Evidence: GERD avg radiance: ${gerdMean.toFixed(4)} (from ${gerdCount} pixels)`);

  if (aswanMean > gerdMean) {
    console.log('A: Yes');
  } else {
    console.log('A: No');
  }
}

